// D-08 W01 AC3 (R092 in design/RULES.md): D-08, its CSV and ROADMAP.md are generated by
// scripts/generate-backlog.py and never edited by hand. The test runs the script in a temporary
// folder and compares its output with the files in the repository.
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

import { afterAll, describe, expect, it } from 'vitest';

import { repoRoot } from './helpers';

const root = repoRoot();
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'sdlc-backlog-'));
afterAll(() => fs.rmSync(tmp, { recursive: true, force: true }));

const OUTPUTS = ['design/D-08-mvp-backlog.md', 'design/D-08-backlog.csv', 'ROADMAP.md'];

describe('W01: the generated backlog files equal the script output (R092)', () => {
  it('scripts/generate-backlog.py writes exactly the committed files', () => {
    fs.mkdirSync(path.join(tmp, 'scripts'));
    fs.mkdirSync(path.join(tmp, 'design'));
    fs.copyFileSync(
      path.join(root, 'scripts/generate-backlog.py'),
      path.join(tmp, 'scripts/generate-backlog.py'),
    );
    const run = spawnSync('python3', ['scripts/generate-backlog.py'], {
      cwd: tmp,
      encoding: 'utf8',
    });
    expect(run.status, run.stderr).toBe(0);
    for (const file of OUTPUTS) {
      // The CSV writer ends rows with CRLF; compare the text, not the line endings.
      const generated = fs.readFileSync(path.join(tmp, file), 'utf8').replace(/\r\n/g, '\n');
      const committed = fs.readFileSync(path.join(root, file), 'utf8').replace(/\r\n/g, '\n');
      expect(committed, `${file}: edit scripts/generate-backlog.py and run it`).toBe(generated);
    }
  });
});
